const dbs:initSqlJs.Database[]=[];afterEach(()=>{vi.restoreAllMocks();for(const db of dbs.splice(0))db.close();});
async function fixture(changeBeforeStart=false,configuredCommander=false){const f=await namedFixture();dbs.push(f.sql);f.sql.run("INSERT INTO account_operators(account_id,operator_id,acquired_at) VALUES('a','op_mira',0)");f.sql.run("UPDATE operator_training_core_slots SET operator_id='op_mira' WHERE account_id='a' AND slot_index=1");const ids=['op_kyle','op_mira','op_reina','op_eve','op_sera'];f.sql.run("UPDATE account_formation SET formation_json=? WHERE account_id='a'",[JSON.stringify({schemaVersion:1,operators:ids.map((operatorId,slot)=>({slot,operatorId}))})]);if(configuredCommander){f.sql.run("INSERT INTO player_profiles(account_id,commander_xp,created_at,updated_at) VALUES('a',999999,0,0)");const config=JSON.parse(String(f.scalar('SELECT config_json FROM balance_config_versions')));f.sql.run('UPDATE balance_config_versions SET config_json=?',[JSON.stringify({...config,commanderTraits:commanderDefinition})]);const store=new CommanderPresetStore(f.env.DB,commanderDefinition.handlers),save={slotId:1 as const,expectedPresetRevision:0,expectedProgressionRevision:1,rulesVersion:commanderDefinition.rulesVersion,traitDefinitionVersion:commanderDefinition.traitDefinitionVersion,ranks:{}};await store.save('a',save,'LOCAL_FIRST_TEST_COMMANDER');await store.activate('a',{slotId:1,expectedPresetRevision:1,expectedProgressionRevision:1,expectedSelectionRevision:0,rulesVersion:save.rulesVersion,traitDefinitionVersion:save.traitDefinitionVersion},'LOCAL_FIRST_TEST_COMMANDER_ACTIVE');}const mira=await captureMiraBasicSource(f.env.DB,'a',{expectedFormationRevision:1,expectedLoadoutRevision:1});if(changeBeforeStart)f.sql.run("UPDATE account_operators SET promotion=1,revision=2 WHERE account_id='a' AND operator_id='op_mira'");const q=await(await f.preview({operationId:'opn_01_last_departure',risk:'I',expectedFormationRevision:1,expectedLoadoutRevision:1,expectedUltimateRevision:0})).json();const preview=await f.env.DB.prepare("SELECT * FROM operation_previews WHERE id=? AND account_id='a'").bind(q.operationPreviewId).first<Parameters<typeof startDeparture>[2]>();if(!preview)throw new Error('LOCAL_PREVIEW_MISSING');const result=await startDeparture(f.env.DB,'a',preview,'LOCAL_MIRA_EFFECTIVE_START',async(p,runId)=>({...JSON.parse(p.preview_json),accepted:true,startStatus:'STARTED',runId,operationPreviewId:q.operationPreviewId,operationId:p.objective,risk:p.risk,balanceVersion:String(p.balance_config_version)}),undefined,f.env.ENVIRONMENT,undefined,new RunEquipmentDepartureProducer(f.env.DB));const runId=String(result.runId),originalSnapshot=String(f.scalar('SELECT snapshot_json FROM run_snapshots')),pin=await readEquipmentDeparturePin(originalSnapshot,{accountId:'a',runId});if(!pin)throw new Error('LOCAL_PIN_MISSING');const request=()=>({runId,expectedInventoryRevision:Number(f.scalar('SELECT revision FROM run_equipment_inventory')),expectedDeparturePinHash:pin.pinHash});const capture=()=>captureMiraEffectiveSource(f.env.DB,'a',request(),mira,mira.packetHash);
 const placement=new EquipmentPlacementStore(f.env.DB,{prepare:async()=>({assertions:[f.env.DB.prepare('INSERT INTO equipment_placement_write_guard(valid) VALUES(1)')]})});
 async function issue(instanceId:string,categoryId='ATK',unique=false,definitionVersion=equipmentCoreStatVersion,enchanted=false,customEnchantment?:Record<string,unknown>,starOverride?:number,setTag='SET05'){const star=starOverride??(unique?3:1),snapshot={version:customEnchantment?.effectId==='EN17'?'equipment.effect-original.v2.20261015':'equipment.effect-original.v1',equipment:{definitionId:'LOCAL_'+categoryId,definitionVersion,star},uniqueEffects:unique?[{effectId:'EQ01',grade:1,definitionVersion:equipmentCoreStatVersion,definitionSnapshot:{fixtureOnly:true}}]:[],enchantment:customEnchantment??(enchanted?{effectId:'EN02',appliedStar:star,definitionVersion,definitionSnapshot:{fixtureOnly:true}}:null)};const original=new EquipmentEffectOriginalStore(f.env.DB,{prepare:async()=>({snapshot,assertions:[f.env.DB.prepare('INSERT INTO equipment_effect_original_write_guard(valid) VALUES(1)')]})});const prepared=await original.prepare('a',runId,{instanceId,sourceItemId:'LOCAL_'+instanceId,expectedInventoryRevision:request().expectedInventoryRevision});await f.env.DB.batch([f.env.DB.prepare("INSERT INTO run_equipment_instances(instance_id,run_id,source_item_id,definition_id,definition_version,category_id,set_tag,star,locked,location_kind,revision) VALUES(?,?,?,?,?,?,?, ?,0,'STORED',1)").bind(instanceId,runId,'LOCAL_'+instanceId,'LOCAL_'+categoryId,definitionVersion,categoryId,setTag,star),...prepared.statements]);}
 async function move(instanceId:string,target:{kind:'operator';wearerId:string;slotIndex:number}|null){return placement.move('a',runId,{commandId:'LOCAL_MOVE_'+crypto.randomUUID(),instanceId,expectedInventoryRevision:request().expectedInventoryRevision,expectedInstanceRevision:Number(f.scalar("SELECT revision FROM run_equipment_instances WHERE instance_id='"+instanceId+"'")),target,expectedTargetInstanceId:null});}
 return {...f,mira,runId,originalSnapshot,request,capture,issue,move};}
it('distinguishes verified empty equipment ledger from missing research and never promotes a partial component',async()=>{const f=await fixture(),p=await f.capture();expect(p.equipment).toMatchObject({inventoryRevision:1,inventoryEmpty:true,equippedEmpty:true,slots:[null,null,null],status:'VERIFIED_CORE_COMPONENT'});expect(p.coreStats?.attack).toEqual({numerator:'30',denominator:'1'});expect(p.research).toMatchObject({status:'SOURCE_OWNER_UNAVAILABLE',modifiers:null,revision:null});expect(p.effectiveStats).toBeNull();expect(p.runtimeSupported).toBe(false);expect(p.missing).toContain('AUTHORITATIVE_RESEARCH_LEDGER_AND_APPLICABILITY');});
it('reads actual equip and unequip via the existing transaction owner, excluding another wearer',async()=>{const f=await fixture();await f.issue('atk');await f.move('atk',{kind:'operator',wearerId:'op_mira',slotIndex:0});const equipped=await f.capture();expect(equipped.coreStats?.attack).toEqual({numerator:'33',denominator:'1'});expect(equipped.equipment.slots[0]?.instanceId).toBe('atk');await f.move('atk',{kind:'operator',wearerId:'op_kyle',slotIndex:0});const other=await f.capture();expect(other.coreStats?.attack).toEqual({numerator:'30',denominator:'1'});expect(other.equipment.inventoryEmpty).toBe(false);expect(other.equipment.equippedEmpty).toBe(true);expect(other.equipment.inventoryRevision).toBeGreaterThan(equipped.equipment.inventoryRevision);await f.move('atk',null);expect((await f.capture()).equipment.equippedEmpty).toBe(true);});
it('does not silently drop unsupported unique effects or categories from a final static value',async()=>{const f=await fixture();await f.issue('unique','ATK',true);await f.move('unique',{kind:'operator',wearerId:'op_mira',slotIndex:0});const p=await f.capture();expect(p.coreStats).toBeNull();expect(p.equipment.blocked.map(x=>x.reason)).toContain('effect_handler_unavailable');expect(p.effectiveStats).toBeNull();await f.move('unique',null);await f.issue('speed','ASPD');await f.move('speed',{kind:'operator',wearerId:'op_mira',slotIndex:0});const speed=await f.capture();expect(speed.equipment.blocked.map(x=>x.reason)).toContain('category_unsupported');expect(speed.coreStats).toBeNull();});
it('refuses an absent inventory ledger rather than manufacturing empty equipment',async()=>{const f=await fixture(),request=f.request();f.sql.run('DELETE FROM run_equipment_inventory');await expect(captureMiraEffectiveSource(f.env.DB,'a',request,f.mira,f.mira.packetHash)).rejects.toThrow('equipment_inventory_state_missing');});
it('rejects wrong account, expected revisions/pin hash and a different source identity',async()=>{const f=await fixture();await expect(captureMiraEffectiveSource(f.env.DB,'b',f.request(),f.mira,f.mira.packetHash)).rejects.toThrow();await expect(captureMiraEffectiveSource(f.env.DB,'a',{...f.request(),expectedInventoryRevision:99},f.mira,f.mira.packetHash)).rejects.toThrow();await expect(captureMiraEffectiveSource(f.env.DB,'a',{...f.request(),expectedDeparturePinHash:'0'.repeat(64)},f.mira,f.mira.packetHash)).rejects.toThrow();const forged=structuredClone(f.mira);forged.ownedSourceHash='sha256:'+'0'.repeat(64);await expect(captureMiraEffectiveSource(f.env.DB,'a',f.request(),forged,f.mira.packetHash)).rejects.toThrow();});
it('rejects inventory changes across the read boundary',async()=>{const f=await fixture(),original=EquipmentInventoryStore.prototype.readInventory;let reads=0;vi.spyOn(EquipmentInventoryStore.prototype,'readInventory').mockImplementation(async function(this:EquipmentInventoryStore,...args){const value=await original.apply(this,args);if(++reads===1)f.sql.run('UPDATE run_equipment_inventory SET revision=revision+1');return value;});await expect(f.capture()).rejects.toMatchObject({code:'combat_mira_effective_source_changed'});});
it('keeps OWN_BASIC unapplied to static ATK and reuses original duplicate/cap resolution',async()=>{const f=await fixture(),p=await f.capture(),effect=p.passive.effect;expect(p.passive.appliedToStaticStats).toBe(false);expect(effect).toEqual({sourceId:'passive:op_mira:OWN_BASIC',group:'NON_EQUIPMENT_OUTGOING',valueBps:1000});const base=p.coreStats!.attack;expect(resolveDirectDamageBudget({base,effects:[effect,effect],defenseBps:0,incomingReductionBps:0}).ordinaryBeforeShield).toBe('33');expect(resolveDirectDamageBudget({base,effects:[effect,{...effect,sourceId:'other',valueBps:99000}],defenseBps:0,incomingReductionBps:0}).ordinaryBeforeShield).toBe('39');});
it('restores the original static component after equipment/growth changes and rejects rehashed candidate content',async()=>{const f=await fixture(),p=await f.capture();await f.issue('atk');await f.move('atk',{kind:'operator',wearerId:'op_mira',slotIndex:0});f.sql.run("UPDATE account_operators SET promotion=2,revision=2 WHERE account_id='a' AND operator_id='op_mira'");const fresh=await f.capture();expect(fresh.coreStats?.attack).toEqual({numerator:'33',denominator:'1'});expect(await readPinnedMiraEffectiveSource(p,p,p.packetHash,'a')).toEqual(p);const forged=structuredClone(p);forged.coreStats!.attack.numerator='999';const {packetHash,...body}=forged;void packetHash;forged.packetHash=await sha256Hex(canonicalJson(body));await expect(readPinnedMiraEffectiveSource(forged,p,p.packetHash,'a')).rejects.toThrow();expect(f.scalar('SELECT snapshot_json FROM run_snapshots')).toBe(f.originalSnapshot);});
