it('maps all three actual slots through the original HP/ATK/DEF calculator',async()=>{const f=await fixture();for(const category of ['HP','ATK','DEF'])await f.issue(category,category);for(const [slotIndex,instanceId] of ['HP','ATK','DEF'].entries())await f.move(instanceId,{kind:'operator',wearerId:'op_mira',slotIndex});const p=await f.capture();expect(p.equipment.slots.map(x=>x?.instanceId)).toEqual(['HP','ATK','DEF']);expect(p.coreStats).toMatchObject({maxHp:1100,attack:{numerator:'33',denominator:'1'},defense:{numerator:'1221',denominator:'10'}});expect(p.effectiveStats).toBeNull();});
it('marks missing effect evidence, unknown original definition and enchantment as unavailable components',async()=>{const f=await fixture();f.sql.run("INSERT INTO run_equipment_instances(instance_id,run_id,source_item_id,definition_id,definition_version,category_id,set_tag,star,locked,location_kind,wearer_kind,wearer_id,slot_index,revision) VALUES('missing',?,'LOCAL_MISSING','LOCAL_ATK',?,'ATK','SET05',1,0,'EQUIPPED','operator','op_mira',0,1)",[f.runId,equipmentCoreStatVersion]);expect((await f.capture()).equipment.blocked.map(x=>x.reason)).toContain('effect_source_missing');await f.move('missing',null);await f.issue('old','ATK',false,'LOCAL_OLD_DEFINITION');await f.move('old',{kind:'operator',wearerId:'op_mira',slotIndex:0});const old=await f.capture();expect(old.coreStats).toBeNull();expect(old.equipment.blocked.map(x=>x.reason)).toContain('definition_unsupported');await f.move('old',null);await f.issue('ench','ATK',false,equipmentCoreStatVersion,true);await f.move('ench',{kind:'operator',wearerId:'op_mira',slotIndex:0});const enchanted=await f.capture();expect(enchanted.coreStats).toBeNull();expect(enchanted.equipment.blocked.map(x=>x.reason)).toContain('effect_handler_unavailable');});
it('rejects a run lifecycle change during the same capture',async()=>{const f=await fixture(),original=EquipmentInventoryStore.prototype.readInventory;let changed=false;vi.spyOn(EquipmentInventoryStore.prototype,'readInventory').mockImplementation(async function(this:EquipmentInventoryStore,...args){const value=await original.apply(this,args);if(!changed){changed=true;f.sql.run("UPDATE runs SET status='COMPLETED' WHERE id=?",[f.runId]);}return value;});await expect(f.capture()).rejects.toMatchObject({code:'combat_mira_effective_source_changed'});});
const firstTestProfile='mira-first-no-effect-test.v1.20261015';
it('applies research NOT_APPLICABLE only to the explicitly selected first-test profile',async()=>{const f=await fixture(),genericBefore=await f.capture(),p=await captureMiraFirstTestSource(f.env.DB,'a',{...f.request(),profile:firstTestProfile},f.mira,f.mira.packetHash);expect(p.research).toMatchObject({status:'NOT_APPLICABLE',modifiers:null,ledgerEvidence:null,policyVersion:'mira-first-test-research-na-20261015',policySource:'44_COMBAT_DETAIL_CONTRACTS.md#mira-first-test-research-na-20261015'});expect(p.originalComponent.research.status).toBe('SOURCE_OWNER_UNAVAILABLE');expect(p.profile).toBe(firstTestProfile);expect(p.staticStatsReady).toBe(true);expect(p.effectiveStats).toEqual({maxHp:1000,attack:{numerator:'30',denominator:'1'},defense:{numerator:'111',denominator:'1'},basicIntervalMs:1800});expect(p).toMatchObject({runtimeSupported:false,canStart:false});expect(p.originalComponent.passive.appliedToStaticStats).toBe(false);expect(p.statStage).toBe('FIRST_TEST_STATIC_BEFORE_DYNAMIC_COMBAT_EFFECTS');expect(p.missing).toContain('ORIGINAL_FIRE_D_CRITICAL_OPPORTUNITY_AND_TARGET_SPECIFIC_EFFECTS');expect(p.originalComponent.passive.effect.valueBps).toBe(1000);expect(p.effectiveStats?.attack).toEqual({numerator:'30',denominator:'1'});expect(await f.capture()).toEqual(genericBefore);});
