it('does not mark equipped core stats as final without the full equipment effect owner',async()=>{const f=await fixture();await f.issue('atk');await f.move('atk',{kind:'operator',wearerId:'op_mira',slotIndex:0});const p=await captureMiraFirstTestSource(f.env.DB,'a',{...f.request(),profile:firstTestProfile},f.mira,f.mira.packetHash);expect(p.research.status).toBe('NOT_APPLICABLE');expect(p.originalComponent.coreStats?.attack).toEqual({numerator:'33',denominator:'1'});expect(p.staticStatsReady).toBe(false);expect(p.effectiveStats).toBeNull();expect(p.unsupported).toContain('FULL_EQUIPMENT_EFFECT_COMPOSITION_UNAVAILABLE');});
