it('pins the first-test policy and original ready state through restore without current gear lookup',async()=>{const f=await fixture(),p=await captureMiraFirstTestSource(f.env.DB,'a',{...f.request(),profile:firstTestProfile},f.mira,f.mira.packetHash);await f.issue('atk');await f.move('atk',{kind:'operator',wearerId:'op_mira',slotIndex:0});const restored=await readPinnedMiraFirstTestSource(p,p,p.packetHash,'a');expect(restored).toEqual(p);expect(restored.staticStatsReady).toBe(true);restored.effectiveStats!.attack.numerator='999';expect(p.effectiveStats!.attack.numerator).toBe('30');const forged=structuredClone(p);forged.research.policyVersion='UNAPPROVED';const {packetHash,...body}=forged;void packetHash;forged.packetHash=await sha256Hex(canonicalJson(body));await expect(readPinnedMiraFirstTestSource(forged,p,p.packetHash,'a')).rejects.toThrow();await expect(readPinnedMiraFirstTestSource(p,p,p.packetHash,'b')).rejects.toThrow();});
