const logicalMultishot=(star=1,bps=1500)=>({version:'multishot-enchant-v1.20261015',appliedStar:star,coefficientBps:bps,maxSecondaryTargets:2,radiusL:{numerator:1,denominator:2},attackEvaluation:'AT_FIRE',targetDefenseEvaluation:'AT_IMPACT'});
// Synthetic catalog binding only. EN02/LOCAL_* is not an operating multishot ID/definition.
async function isolatedBinding(){const body={version:'equipment.multishot-isolated-binding.v1.20261015',sourceStatus:'ISOLATED_LOCAL_FIXTURE',effectId:'EN02',definitionVersion:'LOCAL_MULTISHOT_ENCHANT_V1',catalogVersion:'LOCAL_MULTISHOT_CATALOG_V1',logicalDefinitionVersion:'multishot-enchant-v1.20261015'};return {...body,bindingHash:await sha256Hex(canonicalJson(body))};}
async function equippedMulti(f:Awaited<ReturnType<typeof fixture>>,instanceId:string,currentStar=1,appliedStar=currentStar,bps=appliedStar===1?1500:2500,slotIndex=0){await f.issue(instanceId,'ATK',false,equipmentCoreStatVersion,false,{effectId:'EN02',appliedStar,definitionVersion:'LOCAL_MULTISHOT_ENCHANT_V1',definitionSnapshot:logicalMultishot(appliedStar,bps)},currentStar);await f.move(instanceId,{kind:'operator',wearerId:'op_mira',slotIndex});}
it('distinguishes valid no-enchantment from unbound catalog rather than inventing a formal multishot ID',async()=>{const f=await fixture();const none=await captureEquippedMultishot12Source(f.env.DB,'a',f.request(),f.mira,f.mira.packetHash);expect(none.selection).toBeNull();expect(none.status).toBe('VERIFIED_NO_ENCHANTMENT');await equippedMulti(f,'local-multi');const unknown=await captureEquippedMultishot12Source(f.env.DB,'a',f.request(),f.mira,f.mira.packetHash);expect(unknown.status).toBe('UNSUPPORTED');expect(unknown.blocked.map(x=>x.reason)).toContain('MULTISHOT_CATALOG_BINDING_UNCONFIRMED');expect(unknown.selection).toBeNull();expect(unknown.operatingCatalogBound).toBe(false);expect(unknown.originalComponent.research.status).toBe('SOURCE_OWNER_UNAVAILABLE');});
it('selects exactly one highest original procedure from three stored/equipped instances in an isolated binding',async()=>{const f=await fixture(),binding=await isolatedBinding();await equippedMulti(f,'z',1,1,1500,0);await equippedMulti(f,'b',2,2,2500,1);await equippedMulti(f,'a',2,2,2500,2);const p=await captureEquippedMultishot12Source(f.env.DB,'a',{...f.request(),expectedBindingHash:binding.bindingHash},f.mira,f.mira.packetHash,{read:async()=>structuredClone(binding)});expect(p.status).toBe('ISOLATED_FIXTURE_SELECTED');expect(p.selection).toMatchObject({instanceId:'a',definitionSnapshot:{appliedStar:2,coefficientBps:2500,maxSecondaryTargets:2}});expect(p.slots.filter(x=>x!==null)).toHaveLength(3);expect(p.operatingCatalogBound).toBe(false);expect(p.runtimeSupported).toBe(false);expect(p.startBinding).toBe('READ_ONLY_VIEW_NOT_COMMITTED_START_EXTENSION');expect(p.slots.every(x=>x?.originalHash.match(/^[a-f0-9]{64}$/u))).toBe(true);});
