async function previewStore(f:Awaited<ReturnType<typeof fixture>>,onInspect?:(count:number)=>void){
 let inspections=0;
 f.sql.run('CREATE TABLE LOCAL_preview_eligibility(account_id TEXT,run_id TEXT,revision INTEGER,allowed INTEGER,PRIMARY KEY(account_id,run_id))');f.sql.run('INSERT INTO LOCAL_preview_eligibility VALUES(?,?,1,1)',['a',f.runId]);
 return new EquipmentPlacementStore(f.env.DB,{prepare:async()=>({assertions:[f.env.DB.prepare('INSERT INTO equipment_placement_write_guard VALUES(1)')]}),readPreview:async context=>{onInspect?.(++inspections);
  const row=await f.env.DB.prepare('SELECT revision,allowed FROM LOCAL_preview_eligibility WHERE account_id=? AND run_id=?').bind(context.accountId,context.runId).first<{revision:number;allowed:number}>();
  if(!row)throw new Error('LOCAL_PREVIEW_OWNER_MISSING');return {sourceVersion:'LOCAL_SAFE_PREVIEW_V1',sourceRevision:row.revision,sourceHash:await sha256Hex(canonicalJson({context,row})),allowed:row.allowed===1};
 }});
}
const placementProposal=(f:Awaited<ReturnType<typeof fixture>>,id:string,target:{kind:'operator';wearerId:string;slotIndex:number}|null,displaced:string|null,commandId='preview-placement')=>({commandId,instanceId:id,expectedInventoryRevision:f.request().expectedInventoryRevision,expectedInstanceRevision:Number(f.scalar("SELECT revision FROM run_equipment_instances WHERE instance_id='"+id+"'")),target,expectedTargetInstanceId:displaced});
it('replacement preview prepares the true three-slot assignment, keeps all DB bytes unchanged and matches a later real placement',async()=>{
 const f=await equippedFormalFixture();await f.issue('higher','ATK',false,equipmentCoreStatVersion,false,formalEnchant(2),2,'SET04');const placement=await previewStore(f);
 const {MultishotPresentationSource}=await import('../../apps/game-api/src/equipment-multishot-presentation-source');const owner=new MultishotPresentationSource(f.env.DB,placement),command=placementProposal(f,'higher',{kind:'operator',wearerId:'op_mira',slotIndex:0},'formal');
 const before=f.sql.export(),p=await owner.previewPlacement('a',formalRequest(f),f.mira,f.mira.packetHash,command);
 expect(p.status).toBe('PREVIEW');expect(p.before?.coefficientBps).toBe(1500);expect(p.after?.coefficientBps).toBe(2500);expect(p.after?.selectedInstanceId).toBe('higher');expect(p.after?.basis).toBe('PROPOSED_PLACEMENT_NOT_COMMITTED');expect(p.effectChange).toBe('INCREASED');expect(p.committed).toBe(false);expect(Buffer.from(f.sql.export()).equals(Buffer.from(before))).toBe(true);
 await placement.move('a',f.runId,command);const actual=await owner.current('a',formalRequest(f),f.mira,f.mira.packetHash);expect(actual.selectedInstanceId).toBe(p.after?.selectedInstanceId);expect(actual.coefficientBps).toBe(p.after?.coefficientBps);expect(actual.effectiveStats).toEqual(p.after?.effectiveStats);
 const replay=await owner.previewPlacement('a',formalRequest(f),f.mira,f.mira.packetHash,command);expect(replay.status).toBe('ALREADY_COMMITTED');expect(replay.after).toBeNull();
});
